'use strict';
/**
 * M6 第一批（W25 盤點離線工具、P07 關係會員）自造測試檔。全部是虛構資料（品號 12、345、2000215 等，不含任何真實門市資料）。
 * 執行：node tests/fixtures/m6/build-fixtures.cjs（會覆寫同資料夾內的 .xlsx；結果提交進版控，單元／e2e／parity 測試直接讀檔）。
 *
 * 設計好的數字（庫存：12→10、345→5、2000215→-2、ABC-77→0、7→8、9→3、100→0）：
 *   模組一（外盤 + FKS）：應複盤 = [00000009, 00000100]
 *   模組二（預盤兩檔 + FKS）：有盤差 = 00000007（-3）；無盤差 = 00000012、00000345、00000009；未盤點 = 02000215（庫存 -2）
 *   模組三（改好的內部複盤 + 未盤點）：5 筆，盤差皆 0
 */
const fs = require('node:fs');
const path = require('node:path');
const X = require('xlsx');

const DIR = __dirname;
function write(name, aoa, opts = {}) {
  const sheet = X.utils.aoa_to_sheet(aoa);
  if (opts.merges) sheet['!merges'] = opts.merges;
  const book = X.utils.book_new();
  X.utils.book_append_sheet(book, sheet, opts.sheetName || '工作表1');
  X.writeFile(book, path.join(DIR, name));
}

const baseRows = [
  [12, '測試商品甲', '4710000000012', 10, 'A-01', 'PCS'],
  ['00000345', '測試商品乙', '4710000000345', 5, 'A-02', 'PCS'],
  [2000215, '測試商品丙', '4710002000215', -2, 'B-01', 'BOX'],
  ['ABC-77', '測試商品丁', '4710000000077', 0, 'C-01', 'PCS'],
  [7, '測試商品戊', '4710000000007', 8, 'D-01', 'PCS'],
  [9, '測試商品己', '4710000000009', 3, 'E-01', 'PCS'],
  [100, '測試商品庚', '4710000000100', 0, 'F-01', 'PCS'],
];
const BLANK6 = ['', '', '', '', '', ''];
const M6 = { s: { r: 0, c: 0 }, e: { r: 0, c: 5 } };
const base = (headers, rows = baseRows, blank = BLANK6) => [blank, headers, ...rows];

// ---- 1F 商品檔（第一列空白合併儲存格、第二列標題）
write('base-1f.xlsx', base(['品號', '品名', '條碼', '庫存', '主要儲位', 'UN']), { merges: [M6] });
// 欄位順序不同；庫存別名「重存」、儲位別名「主要庫位」、單位別名「單位」
write('base-1f-reordered.xlsx', base(['條碼', '品名', '品號', '主要庫位', '重存', '單位'], baseRows.map((r) => [r[2], r[1], r[0], r[4], r[3], r[5]])), { merges: [M6] });
// 標題前後有空白（含全形空白）
write('base-1f-spaces.xlsx', base([' 品號', '品名 ', '條碼', ' 庫存', '主要儲位　', 'UN']), { merges: [M6] });
// 標題欄位名稱較長（含括號說明）：includes 比對
write('base-1f-longnames.xlsx', base(['品號', '品名', '條碼', '庫存量(系統)', '主要儲位(1F)', '單位(最小)']), { merges: [M6] });
// 缺欄位
write('base-1f-missing-location.xlsx', base(['品號', '品名', '條碼', '庫存', 'UN'], baseRows.map((r) => [r[0], r[1], r[2], r[3], r[5]]), ['', '', '', '', '']), { merges: [{ s: { r: 0, c: 0 }, e: { r: 0, c: 4 } }] });
write('base-1f-missing-stock.xlsx', base(['品號', '品名', '條碼', '主要儲位', 'UN'], baseRows.map((r) => [r[0], r[1], r[2], r[4], r[5]]), ['', '', '', '', '']), { merges: [{ s: { r: 0, c: 0 }, e: { r: 0, c: 4 } }] });
write('base-1f-missing-barcode.xlsx', base(['品號', '品名', '庫存', '主要儲位', 'UN'], baseRows.map((r) => [r[0], r[1], r[3], r[4], r[5]]), ['', '', '', '', '']), { merges: [{ s: { r: 0, c: 0 }, e: { r: 0, c: 4 } }] });
// 標題在第一列（沒有空白列）：兩版都應失敗
write('base-1f-header-row1.xlsx', [['品號', '品名', '條碼', '庫存', '主要儲位', 'UN'], ...baseRows]);
// 兩個含「庫存」的欄位（庫存金額在前）：兩版都取第一個
write('base-1f-two-stock-cols.xlsx', base(['品號', '品名', '條碼', '庫存金額', '庫存', '主要儲位', 'UN'], baseRows.map((r) => [r[0], r[1], r[2], r[3] * 100, r[3], r[4], r[5]]), ['', '', '', '', '', '', '']));
// 資料列中間有品號空白的列、庫存非數字的列
write('base-1f-blank-code-row.xlsx', base(['品號', '品名', '條碼', '庫存', '主要儲位', 'UN'], [...baseRows.slice(0, 3), ['', '無品號列', '4710000009999', 6, 'Z-01', 'PCS'], ...baseRows.slice(3)]), { merges: [M6] });
write('base-1f-nonnumeric-stock.xlsx', base(['品號', '品名', '條碼', '庫存', '主要儲位', 'UN'], [...baseRows.slice(0, 2), [55, '庫存非數字', '4710000000055', '待確認', 'Y-01', 'PCS']]), { merges: [M6] });
// UN 欄位大小寫
write('base-1f-un-lowercase.xlsx', base(['品號', '品名', '條碼', '庫存', '主要儲位', 'un']), { merges: [M6] });

// ---- 外盤公司原始檔、FKS0701
const extHeader = ['品號', '品名', '條碼', '盤點數量'];
write('external-original.xlsx', [extHeader, [12, '測試商品甲', '4710000000012', 6], [345, '測試商品乙', '4710000000345', 5], [7, '測試商品戊', '4710000000007', 3], [9, '測試商品己', '4710000000009', 3], [100, '測試商品庚', '4710000000100', 1]]);
write('external-clean.xlsx', [extHeader, [12, '測試商品甲', '4710000000012', 6], [345, '測試商品乙', '4710000000345', 5]]);
write('external-dup.xlsx', [extHeader, [12, '測試商品甲', '4710000000012', 6], [7, '測試商品戊', '4710000000007', 3], [12, '測試商品甲', '4710000000012', 1], [7, '測試商品戊', '4710000000007', 2], [345, '測試商品乙', '4710000000345', 5]]);
write('external-missing-col.xlsx', [['品號', '品名', '盤點數量'], [12, '測試商品甲', 6]]);
const fksHeader = ['品號', '品名', '條碼', '盤點數量', '盤點儲位', '備註'];
write('fks0701.xlsx', [fksHeader, [12, '測試商品甲', '4710000000012', 4, 'B-01', ''], [9, '測試商品己', '4710000000009', 3, 'E-01', '']]);
write('fks0701-module1.xlsx', [fksHeader, [12, '測試商品甲', '4710000000012', 4, 'B-01', ''], [9, '測試商品己', '4710000000009', 3, 'E-01', ''], [7, '測試商品戊', '4710000000007', 5, 'D-01', '']]);
write('fks0701-prefixed.xlsx', [['商品品號', '商品名稱', '商品條碼', '實際盤點數量', '盤點儲位'], [12, '測試商品甲', '4710000000012', 4, 'B-01']]);
write('fks0701-missing-col.xlsx', [['品名', '條碼', '盤點儲位'], ['測試商品甲', '4710000000012', 'B-01']]);

// ---- 預盤（多檔）
write('pre-1.xlsx', [['品號', '盤點數量', '盤點儲位'], [12, 6, 'A-01'], [345, 5, 'A-02']]);
write('pre-2.xlsx', [['品號', '盤點數量', '盤點儲位'], [7, 5, 'D-01']]);
write('pre-bad-columns.xlsx', [['品號', '數量'], [12, 1]]);
write('pre-empty.xlsx', [['品號', '盤點數量', '盤點儲位']]);
write('pre-nonnumeric.xlsx', [['品號', '盤點數量', '盤點儲位'], [12, '多少', 'A-01']]);

// ---- 外盤公司盤點 Stock 明細（模組二選填）：同貨架棚板合併
write('external-modified.xlsx', [['貨號', '數量', '貨架', '棚板', '序號'], [100, 2, '1', '2', 1], [100, 3, '1', '2', 2], [100, 1, '2', '1', 3]]);

// ---- 模組三：改好的內部複盤、未盤點
write('internal-edited.xlsx', [['盤點儲位', '該儲位盤點數量', '品號', '品名', 'UN', '條碼', '庫存量', '各式盤點數量加總', '盤差量'], ['D-01', 8, '00000007', '測試商品戊', 'PCS', '4710000000007', 8, 8, 0]]);
write('missing-edited.xlsx', [['品號', '品名', 'UN', '條碼', '庫存量', '主要儲位', '盤點數量'], ['02000215', '測試商品丙', 'BOX', '4710002000215', -2, 'B-01', -2]]);
// 衝突：00000012 同時在無盤差（模組二保留）與複盤；00000007 庫存量 8 與 9 不一致；02000215 在未盤點檔重複
write('internal-conflict.xlsx', [['盤點儲位', '該儲位盤點數量', '品號', '庫存量'], ['A-01', 1, '00000012', 10], ['D-01', 3, '00000007', 8], ['D-02', 5, '00000007', 9]]);
write('missing-conflict.xlsx', [['品號', '庫存量', '盤點數量'], ['02000215', -2, -2], ['02000215', -2, 0]]);

// ---- P07 關係會員銷售明細（年度 2038、門市 VW001；會員編號由測試動態替換，這裡只放樣板）
const salesHeader = ['門市代號', '銷售日期', '會員編號', '品號', '品名', '數量', '金額'];
write('sales-template.xlsx', [salesHeader, ['VW001', '2038/03/01 14:30', 'M6TEMPLATE', 'P001', '測試商品甲', 1, 100], ['VW001', '2038/03/01 14:31', 'M6TEMPLATE', 'P002', '測試商品乙', 2, 250.5]], { sheetName: '銷售' });

console.log('M6 fixtures written to', DIR, fs.readdirSync(DIR).filter((f) => f.endsWith('.xlsx')).length, 'files');
